w.table(['분류','ID 범위','검수 핵심'],[['공통 기능','SFR-001~008','근거·승인·상태·로컬·허용 API'],['업무 기능','SFR-101~504 각 4건','공식 상태와 업무별 실패 복구'],['데이터와 보안','DAR-001, SER-001~003','권한·삭제·개인정보·악성 지시'],['품질과 운영','PER-001~002, COR-001, UIR-001, QUR-001~002','부하·복구·접근성·AI/비AI 검증'],['시험과 사업관리','TER-001, PMR-001~004','추적·변경·인수·권리·교육']],[3,7.4,7])
w.page();w.h('5 추진 일정과 산출물')
w.table(['시점안','주요 작업','완료 증거'],[['1단계 M1','기존 계약·권한·데이터·API·자산 대조','범위표, 요구 기준선, 인력·사용권'],['M2','로컬 PoC·보안·설계·비AI 기준','성능 기록, API 계약, 원가·일정 보정'],['M3~M5','공통 적응과 X02·X04 개발','소스·규칙·근거 사전·단위/계약 시험'],['M6~M7','통합·보안·접근성·업무 검수','결함/재시험, 성능, 사용자 평가'],['M8','4주 시범과 운영 인수','설치·복구 시연, 교육 4회, 인수 목록'],['2단계 M1','추가 권한·범위·API 확정','변경 기준선과 추가 연계 계약'],['M2~M4','X01·X03·X05 구현','기능·계약·회귀 시험'],['M5~M6','통합·4주 시범·인수','보안/부하/업무 검수, 교육 4회']],[2.4,6.4,8.6])
w.p('제안사는 공수 추정과 실제 배치인원을 구분하고 직무·참여율·월별 투입을 제출하여야 한다. 발주기관은 업무 기준·데이터·연계 접근과 검토자를 제공하며, 미제공 사유·영향·복구 계획을 공동 이슈대장으로 관리한다.')
w.h('6 검수와 장애 복구',2)
