w.table(['기술 검토 항목','배점안','확인 증거'],[['업무·국민 가치·비중복',20,'서비스 범위와 비AI 비교'],['로컬 AI·근거·검증',25,'실제 모델/자산 데모와 시험'],['연계·보안·복구',25,'계약·권한·재개·실패 증거'],['수행인력·일정·관리',15,'배치표·협력 범위·변경 절차'],['납품·인수·운영',15,'재설치·교육·지원·권리'],['합계',100,'기술 내부 평가 비중 합계']],[7,2,8.4])
